CREATE TABLE IF NOT EXISTS "USUARIO" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome_usuario" VARCHAR(100) NOT NULL UNIQUE,
	"email" VARCHAR(100) NOT NULL UNIQUE,
	"senha" VARCHAR(100) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "ARTISTA" (
	"id_artista" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome_artista" VARCHAR(100) NOT NULL,
	PRIMARY KEY("id_artista")
);

CREATE TABLE IF NOT EXISTS "GENERO" (
	"id_genero" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome_genero" VARCHAR(100) NOT NULL,
	PRIMARY KEY("id_genero")
);

CREATE TABLE IF NOT EXISTS "ALBUM" (
	"id_album" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome_album" VARCHAR(100) NOT NULL,
	"ano_album" INTEGER NOT NULL,
	"id_artista" INTEGER NOT NULL,
	PRIMARY KEY("id_album")
);

CREATE TABLE IF NOT EXISTS "MUSICA" (
	"id_musica" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"titulo" VARCHAR(100) NOT NULL,
	"duração" INTEGER NOT NULL,
	"id_album" INTEGER NOT NULL,
	"id_genero" INTEGER NOT NULL,
	PRIMARY KEY("id_musica")
);

CREATE TABLE IF NOT EXISTS "PLAYLIST" (
	"id_playlist" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome_playlist" VARCHAR(100) NOT NULL,
	"id_usuario" INTEGER NOT NULL,
	PRIMARY KEY("id_playlist")
);

CREATE TABLE IF NOT EXISTS "PLAYLIST_MUSICA" (
	"id_playlist" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_musica" INTEGER NOT NULL,
	PRIMARY KEY("id_playlist", "id_musica")
);

ALTER TABLE "ALBUM"
ADD FOREIGN KEY("id_artista") REFERENCES "ARTISTA"("id_artista")
ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "MUSICA"
ADD FOREIGN KEY("id_album") REFERENCES "ALBUM"("id_album")
ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "MUSICA"
ADD FOREIGN KEY("id_genero") REFERENCES "GENERO"("id_genero")
ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "PLAYLIST"
ADD FOREIGN KEY("id_usuario") REFERENCES "USUARIO"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "PLAYLIST_MUSICA"
ADD FOREIGN KEY("id_playlist") REFERENCES "PLAYLIST"("id_playlist")
ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "PLAYLIST_MUSICA"
ADD FOREIGN KEY("id_musica") REFERENCES "MUSICA"("id_musica")
ON UPDATE NO ACTION ON DELETE NO ACTION;